# generated by xerunner of unknown revision from xerunner/xex/plugin.py by `xerunner alfred plugin-kit`; change it there, not here
"""Compiling a console plugin and packing it, on Linux and with no XDK.

The toolchain is `gcc-powerpc-linux-gnu` and `write.py`. What the XDK's compiler would
give that gcc does not is the Windows PowerPC ABI -- frame layout, the `__savegprlr`
prologue helpers, `.pdata` written for you. None of that matters for a leaf `DllMain`,
because arguments in r3-r10 and the return in r3 agree between the two; it starts to
matter for a function that calls out with more than eight arguments. `kcall.S`, linked
into every plugin, bridges that one place: `kcall9` puts a ninth argument where the
console's convention has it.

Every number below was read off `xwifi.xex` as the console's own filesystem holds it --
a plugin that loads -- and `write.py` records the container's side:

* the layout is `.text` at 0x1000, then the import address table, then `.data`, then
  `.pdata`, then a `.pad` out to the 0x8000 an image has to reach;
* the address table holds one word an import, the bare ordinal, which the loader
  rewrites;
* a thunk is four words -- `0x010000NN`, `0x020000NN`, `mtctr r11`, `bctr` -- so the
  table's entry and the thunk's two placeholders carry the same ordinal, and generating
  both from one list is what keeps them that way;
* `.pdata` is one entry a function we ship, sorted by address: the three thunks of that
  plugin are four instructions each and its `DllMain` is two.

The linker script is generated here rather than kept beside the sources, because it and
the container encode the same addresses: nothing relocates these images -- there is no
`.reloc` -- so a data reference is resolved against the address the script gave and read
from wherever the container mapped it. One base address goes in and both come out of it.
Letting `.data` follow `.text` contiguously, which is the obvious script, puts a string
just past the code while the table sits on the next page.

Two link passes, because where `.data` goes depends on how big `.text` turned out and
nothing knows that until it has been linked once.

**The ordinals are the caller's and have no default.** A plugin calls the kernel by
number, a wrong number does not fail to link -- it calls a different, real kernel
function -- and the numbers were renumbered more than once, so a table right for one
kernel is quietly wrong for another. `--ordinals` names a file of `name ordinal`
lines, or `--import name=ordinal` gives them one at a time.

This file, `write.py` and `kcall.S` need nothing beside the standard library and the
toolchain, so a plugin's own tree can carry the three and run `python3 plugin.py` --
which is what `xerunner alfred plugin-kit` copies there. `xerunner xex create-plugin`
is the same options over the same `build`.
"""

import os
import sys
import shutil
import struct
import subprocess
import argparse
import itertools

try:
    from . import write
except ImportError:
    # Run as a script out of a plugin's tree, with `write.py` beside it.
    import write

TOOLS = {"gcc": "powerpc-linux-gnu-gcc", "ld": "powerpc-linux-gnu-ld",
         "objcopy": "powerpc-linux-gnu-objcopy", "nm": "powerpc-linux-gnu-nm"}
FLAGS = ["-m32", "-mbig-endian", "-O2", "-ffreestanding", "-fno-builtin", "-nostdlib"]

# A free slot in the band DashLaunch loads plugins into. The console's own are at
# 0x91000000 (xbdm), 0x91800000 (ftpdll), 0x91900000 (jrpc2), 0x91df0000 (usbdsec) and
# 0x91f00000 (launch), so two resident at once need different bases.
BASE = 0x91C00000


def available() -> dict:
    """Each tool this needs and whether it is installed."""
    return {name: shutil.which(tool) is not None for name, tool in TOOLS.items()}


def _run(command: list) -> str:
    done = subprocess.run(command, capture_output=True, text=True)
    if done.returncode:
        raise ValueError("%s failed: %s" % (os.path.basename(command[0]),
                                            done.stderr.strip() or done.returncode))
    return done.stdout


def ordinals(path: str) -> dict:
    """A name-to-ordinal table out of a text file: `name ordinal` or `name = ordinal`
    a line, `#` starting a comment, blank lines passed over."""
    out = {}
    with open(path, encoding="utf-8", errors="replace") as handle:
        for number, line in enumerate(handle, 1):
            said = line.split("#", 1)[0].replace("=", " ").split()
            if not said:
                continue
            if len(said) != 2:
                raise ValueError("%s:%d is not `name ordinal`: %r"
                                 % (path, number, line.strip()))
            try:
                out[said[0]] = int(said[1], 0)
            except ValueError:
                raise ValueError("%s:%d states %r where an ordinal should be"
                                 % (path, number, said[1])) from None
    if not out:
        raise ValueError("%s names no ordinals" % path)
    return out


def _symbols(tool: str, where: str) -> tuple:
    """`(defined, undefined)` symbol names in an object or a linked image."""
    defined, undefined = set(), set()
    for line in _run([tool, where]).splitlines():
        said = line.split()
        if len(said) == 2 and said[0] == "U":
            undefined.add(said[1])
        elif len(said) == 3:
            defined.add(said[2])
    return defined, undefined


def _addresses(tool: str, where: str) -> dict:
    """Every symbol a linked image defines, by name, with its address."""
    out = {}
    for line in _run([tool, where]).splitlines():
        said = line.split()
        if len(said) == 3:
            out[said[2]] = int(said[0], 16)
    return out


def _thunks(wanted: list, into: str) -> str:
    """The import thunks, as assembly, generated from the one import list the address
    table is generated from -- so a thunk without a matching entry cannot happen."""
    body = ["/* Generated by xerunner; do not edit. Four words an import: the two the",
            "   loader rewrites, then an indirect branch. */",
            '\t.section .thunks,"ax",@progbits']
    for name, ordinal in wanted:
        body += ["\t.globl %s" % name, "%s:" % name,
                 "\t.long 0x%08x" % (0x01000000 | ordinal),
                 "\t.long 0x%08x" % (0x02000000 | ordinal),
                 "\tmtctr 11", "\tbctr"]
    path = os.path.join(into, "thunks.generated.S")
    with open(path, "w") as handle:
        handle.write("\n".join(body) + "\n")
    return path


def _script(base: int, data: int, into: str) -> str:
    """The linker script for one base and one address for the data.

    `.sdata` and `.sbss` are PowerPC's small-data sections and gcc puts small globals
    there without being asked: a section the container does not carry keeps its address
    and loses its contents, so an initialised global would arrive as zeros.
    """
    text = """ENTRY(DllMain)
SECTIONS {
  . = 0x%08X;
  .text : { *(.text) *(.text.*) *(.thunks) }
  . = 0x%08X;
  .data : { *(.rodata) *(.rodata.*) *(.data) *(.data.*)
            *(.sdata) *(.sdata.*) *(.sdata2) *(.sdata2.*)
            *(.bss) *(.sbss) *(.sbss.*) *(COMMON) }
  /DISCARD/ : { *(.comment) *(.note*) *(.eh_frame*) }
}
""" % (base + 0x1000, data)
    path = os.path.join(into, "link.generated.ld")
    with open(path, "w") as handle:
        handle.write(text)
    return path


def _section(tool: str, elf: str, name: str) -> bytes:
    done = subprocess.run([tool, "-O", "binary", "--only-section", name, elf,
                           "/dev/stdout"], capture_output=True)
    return done.stdout if not done.returncode else b""


def _runtime(rva: int, length: int) -> bytes:
    """One `.pdata` entry: where a function starts, and its length in instructions
    with the bit that says it is 32-bit. Measured on a plugin that loads."""
    return struct.pack(">2I", rva, (length // 4) << 2 | 2)


def build(sources: list, into: str, table: dict | None = None,
          given: dict | None = None, base: int = BASE,
          name: str = "plugin.dll", includes: tuple = (),
          defines: tuple = ()) -> dict:
    """Compile, link and pack `sources`; what was built and what went in it.

    The kernel imports are whatever the objects reference and none of them defines, so
    the list is a fact about the code rather than something kept in step with it by
    hand. `table` resolves those names to ordinals and `given` pins any of them.
    """
    missing = [one for one, here in available().items() if not here]
    if missing:
        raise ValueError("%s not installed (gcc-powerpc-linux-gnu and "
                         "binutils-powerpc-linux-gnu)"
                         % ", ".join(TOOLS[one] for one in missing))
    os.makedirs(into, exist_ok=True)
    flags = FLAGS + ["-I" + one for one in includes] + ["-D" + one for one in defines]
    objects = []
    for source in [*sources, os.path.join(os.path.dirname(__file__), "kcall.S")]:
        out = os.path.join(into, os.path.basename(source) + ".o")
        _run([TOOLS["gcc"], *flags, "-c", source, "-o", out])
        objects.append(out)
    defined, undefined = set(), set()
    for one in objects:
        held, wanted = _symbols(TOOLS["nm"], one)
        defined |= held
        undefined |= wanted
    known = dict(table or {})
    known.update(given or {})
    wanted = sorted(undefined - defined)
    unknown = [one for one in wanted if one not in known]
    if unknown:
        raise ValueError("not defined here and no ordinal given for: %s (a compiler "
                         "helper wants -ffreestanding; a typo wants fixing)"
                         % ", ".join(unknown))
    imports = [(one, known[one]) for one in wanted]
    # After the sources and before the thunks: the thunks define exactly what this
    # read as undefined.
    _run([TOOLS["gcc"], *flags, "-c", _thunks(imports, into),
          "-o", os.path.join(into, "thunks.o")])
    objects.append(os.path.join(into, "thunks.o"))
    elf = os.path.join(into, "plugin.elf")
    iat = b"".join(struct.pack(">I", ordinal) for _, ordinal in imports)

    def linked(data: int) -> tuple:
        if os.path.exists(elf):
            os.remove(elf)
        _run([TOOLS["ld"], "-T", _script(base, data, into), *objects, "-o", elf])
        return (_section(TOOLS["objcopy"], elf, ".text"),
                _section(TOOLS["objcopy"], elf, ".data"))
    text, _ = linked(base + 0x1000 + 0x100000)
    iat_rva = 0x1000 + -(-len(text) // 0x1000) * 0x1000
    data_rva = iat_rva + -(-len(iat) // 0x1000) * 0x1000
    grown, data = linked(base + data_rva)
    if len(grown) != len(text):
        raise ValueError("the code changed size between the two link passes")
    held = _addresses(TOOLS["nm"], elf)
    if "DllMain" not in held:
        raise ValueError("this plugin defines no DllMain")
    sections = [write.Section(".text", grown, 0x1000, 0x60000020),
                write.Section(".rdata", iat, iat_rva, 0x40000040)]
    if data:
        sections.append(write.Section(".data", data, data_rva, 0xC0000040))
    # One entry a function we ship, the thunks at four instructions each and DllMain
    # measured to the next symbol above it so a growing function does not lie.
    above = sorted(one for one in held.values() if one > held["DllMain"])
    entries = [(held[one] - base, 0x10) for one, _ in imports if one in held]
    entries.append((held["DllMain"] - base,
                    max(8, above[0] - held["DllMain"] if above else 8)))
    pdata = b"".join(_runtime(rva, length) for rva, length in sorted(entries))
    pdata_rva = max(one.rva + one.span for one in sections)
    sections.append(write.Section(".pdata", pdata, pdata_rva, 0x40000040))
    end = max(one.rva + one.span for one in sections)
    if end < write.SMALLEST:
        # A real section and not just a longer image: the descriptors have to describe
        # every page the loader maps, and padding the image alone leaves pages no hash
        # reaches.
        sections.append(write.Section(".pad", bytes(write.SMALLEST - end), end,
                                      0xC0000040))
    ordered = sorted(sections, key=lambda one: one.rva)
    for earlier, later in itertools.pairwise(ordered):
        if earlier.rva + earlier.span > later.rva:
            raise ValueError("%s ends at %#x and %s starts at %#x -- they overlap"
                             % (earlier.name, earlier.rva + earlier.span, later.name,
                                later.rva))
    image = write.build_pe(sections, base, held["DllMain"] - base,
                           {3: (pdata_rva, len(pdata))})
    # Two addresses an import, in the order the table holds them: its slot and its
    # thunk. The kernel's identity is what a plugin that loads states.
    addresses = []
    for index, (one, _) in enumerate(imports):
        addresses += [base + iat_rva + index * 4, held.get(one, 0)]
    record = write.library(0, addresses, 0x45DC17E0, 0x20518700, 0x20074500)
    blob = write.build_xex(image, base, held["DllMain"], sections, [record],
                           name=name)
    out = os.path.join(into, "plugin.xex")
    with open(out, "wb") as handle:
        handle.write(blob)
    return {"out": out, "elf": elf, "base": base, "entry": held["DllMain"],
            "image": len(image), "container": len(blob),
            "imports": imports, "symbols": held,
            "sections": [(one.name, one.rva, len(one.data)) for one in ordered]}


def arguments(parser) -> None:
    """The options of a build, for `create-plugin` and for this file run alone."""
    parser.description = ("Compile C and assembly with a PowerPC gcc and pack a "
                          "container the console loads.")
    parser.add_argument("sources", nargs="+", help="the .c and .S files")
    parser.add_argument("--into", required=True, help="where the build goes")
    parser.add_argument("--ordinals", default="",
                        help="a file of `name ordinal` lines for the kernel calls; a "
                        "wrong number does not fail to link, it calls another real "
                        "function, so there is no default")
    parser.add_argument("--import", dest="imports", action="append", default=[],
                        metavar="NAME=ORDINAL", help="one ordinal, instead of a file")
    parser.add_argument("--base", type=lambda text: int(text, 0), default=BASE,
                        help="where it loads; two plugins resident at once need two "
                        "(default %#x)" % BASE)
    parser.add_argument("--name", default="plugin.dll", help="the name it reports")
    parser.add_argument("-I", dest="includes", action="append", default=[],
                        metavar="DIR")
    parser.add_argument("-D", dest="defines", action="append", default=[],
                        metavar="NAME[=VALUE]")


def from_arguments(args) -> dict:
    """`build` over what `arguments` parsed; what was built, each value printable."""
    table = ordinals(args.ordinals) if args.ordinals else {}
    given = {}
    for one in args.imports:
        name, sign, number = one.partition("=")
        if not sign:
            raise ValueError("--import takes NAME=ORDINAL, and %r has no '='" % one)
        given[name] = int(number, 0)
    found = build(args.sources, args.into, table, given, args.base, args.name,
                  tuple(args.includes), tuple(args.defines))
    said = {key: value for key, value in found.items() if key != "symbols"}
    said["imports"] = ", ".join("%s=%d" % one for one in found["imports"])
    said["sections"] = ", ".join("%s@%#x+%#x" % one for one in found["sections"])
    return said


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    arguments(parser)
    try:
        said = from_arguments(parser.parse_args())
    except ValueError as why:
        sys.exit("plugin.py: %s" % why)
    for key, value in said.items():
        hexadecimal = key in ("base", "entry", "image", "container")
        print("%-9s %s" % (key, "%#x" % value if hexadecimal else value))
